using System.Text.Json;
using DotYjs.Lib0;

namespace DotYjs.Tests;

/// <summary>
/// Wire-compatibility tests against fixtures generated by the real JavaScript yjs library
/// (see tests/interop/gen-fixtures.mjs). Also writes .NET-generated fixtures that are verified by
/// tests/interop/check-dotnet-updates.mjs.
/// </summary>
public class InteropTests
{
    internal static readonly string FixtureDir = FindFixtureDir();
    private static readonly JsonDocument Fixtures = JsonDocument.Parse(File.ReadAllText(Path.Combine(FixtureDir, "js-fixtures.json")));

    private static string FindFixtureDir()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir != null && !Directory.Exists(Path.Combine(dir.FullName, "tests", "interop", "fixtures"))) dir = dir.Parent;
        if (dir == null) throw new InvalidOperationException("fixtures directory not found; run `npm run gen` in tests/interop");
        return Path.Combine(dir.FullName, "tests", "interop", "fixtures");
    }

    internal static JsonElement Fixture(string name) => Fixtures.RootElement.GetProperty(name);

    private static byte[] B64(JsonElement e, string name) => Convert.FromBase64String(e.GetProperty(name).GetString()!);

    private static string DocJson(Doc doc) => JsonValues.Stringify(doc.ToJSON());

    /// <summary>Instantiates the typed root types of a freshly decoded doc (like a JS client would) so ToJSON works.</summary>
    private static void TouchRoots(Doc doc, JsonElement f)
    {
        foreach (var p in f.GetProperty("roots").EnumerateObject())
        {
            switch (p.Value.GetString())
            {
                case "YText": doc.GetText(p.Name); break;
                case "YMap": doc.GetMap(p.Name); break;
                case "YArray": doc.GetArray(p.Name); break;
                case "YXmlFragment": doc.GetXmlFragment(p.Name); break;
                case "YXmlElement": doc.GetXmlElement(p.Name); break;
            }
        }
    }

    private static Dictionary<string, string> RootKinds(Doc doc) => doc.Share.ToDictionary(kv => kv.Key, kv => kv.Value.GetType().Name);

    private static string DeltaJson(YText t) => JsonValues.Stringify(t.ToDelta().Select(op => op.ToDictionary()).ToList());

    public static IEnumerable<object[]> ScenarioNames() => Scenarios.Keys.Select(k => new object[] { k });

    [Theory]
    [MemberData(nameof(ScenarioNames))]
    public void Js_Update_Decodes_And_ReEncodes_Identically(string name)
    {
        var f = Fixtures.RootElement.GetProperty(name);
        var expectedJson = f.GetProperty("json").GetString();
        var v1 = B64(f, "updateV1");
        var v2 = B64(f, "updateV2");

        // v1
        var d1 = new Doc();
        UpdateCodec.ApplyUpdate(d1, v1);
        TouchRoots(d1, f);
        Assert.Equal(expectedJson, DocJson(d1));
        Assert.Equal(v1, UpdateCodec.EncodeStateAsUpdate(d1));
        Assert.Equal(v2, UpdateCodec.EncodeStateAsUpdateV2(d1));
        Assert.Equal(B64(f, "stateVector"), UpdateCodec.EncodeStateVector(d1));

        // v2
        var d2 = new Doc();
        UpdateCodec.ApplyUpdateV2(d2, v2);
        TouchRoots(d2, f);
        Assert.Equal(expectedJson, DocJson(d2));
        Assert.Equal(v1, UpdateCodec.EncodeStateAsUpdate(d2));

        // incremental updates + merge
        var incremental = f.GetProperty("incrementalUpdates").EnumerateArray().Select(u => Convert.FromBase64String(u.GetString()!)).ToList();
        var d3 = new Doc();
        foreach (var u in incremental) UpdateCodec.ApplyUpdate(d3, u);
        TouchRoots(d3, f);
        Assert.Equal(expectedJson, DocJson(d3));
        Assert.Equal(B64(f, "mergedIncremental"), Updates.MergeUpdates(incremental));

        // conversions
        Assert.Equal(B64(f, "convertedV1ToV2"), Updates.ConvertUpdateFormatV1ToV2(v1));
        Assert.Equal(B64(f, "convertedV2ToV1"), Updates.ConvertUpdateFormatV2ToV1(v2));

        if (f.GetProperty("textDelta").ValueKind == JsonValueKind.String)
        {
            Assert.Equal(f.GetProperty("textDelta").GetString(), DeltaJson(d1.GetText("t")));
        }
        if (f.GetProperty("xml").ValueKind == JsonValueKind.String)
        {
            Assert.Equal(f.GetProperty("xml").GetString(), d1.GetXmlFragment("x").ToString());
        }
    }

    [Theory]
    [MemberData(nameof(ScenarioNames))]
    public void DotNet_Produces_Identical_Bytes_To_Js(string name)
    {
        var f = Fixtures.RootElement.GetProperty(name);
        var doc = new Doc { ClientID = f.GetProperty("clientID").GetInt64() };
        var incremental = new List<byte[]>();
        doc.Update += (u, _, _, _) => incremental.Add(u);
        Scenarios[name](doc);
        Assert.Equal(f.GetProperty("json").GetString(), DocJson(doc));
        Assert.Equal(B64(f, "updateV1"), UpdateCodec.EncodeStateAsUpdate(doc));
        Assert.Equal(B64(f, "updateV2"), UpdateCodec.EncodeStateAsUpdateV2(doc));
        var jsIncremental = f.GetProperty("incrementalUpdates").EnumerateArray().Select(u => u.GetString()!).ToList();
        Assert.Equal(jsIncremental, incremental.Select(Convert.ToBase64String).ToList());
    }

    [Fact]
    public void Concurrent_Js_Updates_Converge()
    {
        var f = Fixtures.RootElement.GetProperty("concurrent");
        var u1 = B64(f, "update1");
        var u2 = B64(f, "update2");
        foreach (var (order, jsonKey) in new[] { (new[] { u1, u2 }, "json"), (new[] { u2, u1 }, "json21") })
        {
            var d = new Doc();
            foreach (var u in order) UpdateCodec.ApplyUpdate(d, u);
            TouchRoots(d, f);
            Assert.Equal(f.GetProperty("text").GetString(), d.GetText("t").ToString());
            Assert.Equal(f.GetProperty(jsonKey).GetString(), DocJson(d));
            Assert.Equal(B64(f, "finalV1"), UpdateCodec.EncodeStateAsUpdate(d));
        }
        Assert.Equal(B64(f, "merged"), Updates.MergeUpdates(new[] { u1, u2 }));
    }

    [Fact]
    public void Write_DotNet_Fixtures_For_Js_Verification()
    {
        var result = new Dictionary<string, object?>();
        foreach (var (name, scenario) in Scenarios)
        {
            var doc = new Doc { ClientID = 5000 };
            var incremental = new List<string>();
            doc.Update += (u, _, _, _) => incremental.Add(Convert.ToBase64String(u));
            scenario(doc);
            result[name] = new Dictionary<string, object?>
            {
                ["roots"] = RootKinds(doc),
                ["updateV1"] = Convert.ToBase64String(UpdateCodec.EncodeStateAsUpdate(doc)),
                ["updateV2"] = Convert.ToBase64String(UpdateCodec.EncodeStateAsUpdateV2(doc)),
                ["incrementalUpdates"] = incremental,
                ["json"] = DocJson(doc),
                ["textDelta"] = doc.Share.ContainsKey("t") ? DeltaJson(doc.GetText("t")) : null,
            };
        }
        File.WriteAllText(Path.Combine(FixtureDir, "dotnet-fixtures.json"), JsonValues.Stringify(result));
    }

    private static Dictionary<string, object?> Attrs(params (string, object?)[] kv) => kv.ToDictionary(x => x.Item1, x => x.Item2);

    /// <summary>The same scenarios as in gen-fixtures.mjs, written with the .NET API.</summary>
    private static readonly Dictionary<string, Action<Doc>> Scenarios = new()
    {
        ["text_basic"] = doc =>
        {
            var t = doc.GetText("t");
            t.Insert(0, "hello world");
            t.Delete(5, 6);
            t.Insert(5, ", yjs 🙂");
        },
        ["text_formatting"] = doc =>
        {
            var t = doc.GetText("t");
            t.Insert(0, "hello world");
            t.Format(0, 5, Attrs(("bold", true)));
            t.Format(3, 4, Attrs(("italic", true), ("color", "#f00")));
            t.InsertEmbed(3, Attrs(("image", "x.png")));
            t.Insert(11, "tail", Attrs(("bold", null)));
            t.SetAttribute("meta", Attrs(("a", 1L)));
        },
        ["map_values"] = doc =>
        {
            var m = doc.GetMap("m");
            m.Set("int", 42L);
            m.Set("neg", -7L);
            m.Set("float", 1.5);
            m.Set("big", 12345678901.25);
            m.Set("str", "héllo");
            m.Set("bool", true);
            m.Set<object?>("null", null);
            m.Set("obj", Attrs(("a", new List<object?> { 1L, 2L, Attrs(("b", "c")) }), ("d", null)));
            m.Set("bin", new byte[] { 1, 2, 3, 255 });
            m.Set("replace", 1L);
            m.Set("replace", 2L);
            m.Set("deleted", "x");
            m.Delete("deleted");
        },
        ["array_nested"] = doc =>
        {
            var a = doc.GetArray("a");
            a.Push(1L, "two", true, null, Attrs(("k", "v")), new List<object?> { 1L, 2L });
            a.Insert(2, "inserted");
            a.Delete(0, 1);
            var sub = new YMap();
            a.Push(sub);
            sub.Set("inner", new YArray());
            ((YArray)sub.Get("inner")!).Push("deep");
            var t = new YText();
            a.Push(t);
            t.Insert(0, "nested text");
        },
        ["xml"] = doc =>
        {
            var f = doc.GetXmlFragment("x");
            var p = new YXmlElement("p");
            f.Insert(0, p);
            p.SetAttribute("class", "a");
            p.SetAttribute("id", "z");
            var txt = new YXmlText();
            p.Insert(0, txt);
            txt.Insert(0, "hi there");
            txt.Format(0, 2, Attrs(("b", new Dictionary<string, object?>())));
            var div = new YXmlElement("div");
            f.Push(div);
            div.Insert(0, new YXmlText("x"));
            f.Delete(1, 1);
        },
        ["many_ops"] = doc =>
        {
            var t = doc.GetText("t");
            for (int i = 0; i < 200; i++)
            {
                t.Insert(i % 7, "ab");
                if (i % 3 == 0) t.Delete(0, 1);
            }
            var a = doc.GetArray("a");
            for (int i = 0; i < 100; i++) a.Insert(i % 5, (long)i);
            for (int i = 0; i < 30; i++) a.Delete(i, 1);
        },
    };
}
